from ortools.linear_solver import pywraplp
import json

def main():
    solver = pywraplp.Solver.CreateSolver("SCIP")
    if not solver:
        return

    T = 15
    D = 5

    cost = {
        1: 10, 2: 6, 3: 12, 4: 5, 5: 9,
        6: 7, 7: 15, 8: 10, 9: 4, 10: 11,
        11: 8, 12: 6, 13: 17, 14: 9, 15: 7
    }

    cover = {
        1: {1, 2},
        2: {1},
        3: {2, 3, 4},
        4: {3},
        5: {4, 5},
        6: {5},
        7: {1, 3, 5},
        8: {2, 4},
        9: {1},
        10: {2, 3},
        11: {3, 4},
        12: {4},
        13: {1, 2, 5},
        14: {3, 5},
        15: {5}
    }

    x = {}
    for t in range(1, T + 1):
        x[t] = solver.BoolVar(f"x[{t}]")

    for d in range(1, D + 1):
        covering_teams = []
        for t in range(1, T + 1):
            if d in cover[t]:
                covering_teams.append(x[t])

        solver.Add(sum(covering_teams) == 1)

    objective = solver.Sum(cost[t] * x[t] for t in range(1, T + 1))
    solver.Minimize(objective)

    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL:
        selected_teams_binary = []
        for t in range(1, T + 1):
            if x[t].solution_value() > 0.5:
                selected_teams_binary.append(1)
            else:
                selected_teams_binary.append(0)
        total_cost = int(solver.Objective().Value())
        print(json.dumps({
            "selected_teams": selected_teams_binary,
            "total_cost": total_cost
        }))
    else:
        print(json.dumps({
            "selected_teams": [],
            "total_cost": 0
        }))

if __name__ == "__main__":
    main()
